// main.rs
use aws_sdk_s3::Client;
use lambda_runtime::{run, service_fn, Error, LambdaEvent};
use serde_json::{json, Value};
use std::env;

#[tokio::main]
async fn main() -> Result<(), Error> {
    let config = aws_config::load_from_env().await;
    let s3 = Client::new(&config);
    run(service_fn(|event: LambdaEvent<Value>| handler(&s3, event))).await
}

async fn handler(s3: &Client, event: LambdaEvent<Value>) -> Result<Value, Error> {
    let bucket = env::var("BUCKET_NAME")?;
    let key = event.payload["key"].as_str().ok_or("missing key")?;
    let obj = s3.get_object().bucket(&bucket).key(key).send().await?;
    let bytes = obj.body.collect().await?.into_bytes();
    let content = String::from_utf8(bytes.to_vec())?;
    Ok(json!({ "statusCode": 200, "body": content }))
}
